<script>
(()=>{const form=document.getElementById('checkout-form'),steps=document.querySelectorAll('[data-checkout-step]'),labels=document.querySelectorAll('[data-step-label]');function showStep(name){steps.forEach(step=>step.classList.toggle('hidden',step.dataset.checkoutStep!==name));labels.forEach(label=>{const active=label.dataset.stepLabel===name;label.classList.toggle('bg-emerald-800',active);label.classList.toggle('text-white',active);label.classList.toggle('text-slate-400',!active)});window.scrollTo({top:0,behavior:'smooth'})}document.getElementById('continue-payment').addEventListener('click',()=>{const fields=[...form.querySelectorAll('[data-checkout-step="details"] input,[data-checkout-step="details"] textarea')];const invalid=fields.find(field=>!field.checkValidity());if(invalid){invalid.reportValidity();invalid.focus();return}showStep('payment')});document.getElementById('back-details').addEventListener('click',()=>showStep('details'));const proofInput=document.getElementById('proof-input'),proofAction=document.getElementById('proof-action'),proofText=document.getElementById('proof-action-text');proofInput.addEventListener('change',()=>{if(!proofInput.files.length)return;proofInput.disabled=true;proofAction.classList.add('pointer-events-none','opacity-70');proofText.textContent='Mengirim pesanan…';proofInput.disabled=false;form.requestSubmit()});@if($errors->has('proof')) showStep('payment'); @endif})();
</script>
